    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        occupied = [c for c, v in enumerate(row) if v != bg]
        if not occupied:
            continue
        last = occupied[-1]
        if last == w - 1:
            continue

        extend = False

        # Repeated row prefix, with another occurrence continuing farther.
        for rr, other in enumerate(grid):
            if rr != r and other[:last + 1] == row[:last + 1]:
                if any(v != bg for v in other[last + 1:]):
                    extend = True
                    break

        # A long rightmost run close to the edge is an interrupted stripe.
        start = last
        while start > 0 and row[start - 1] == row[last]:
            start -= 1
        run = last - start + 1
        if last >= 0.6 * w and run >= 0.25 * w:
            extend = True

        # Repeated motifs may be shifted horizontally between copies.
        if not extend and last >= 2:
            for rr, other in enumerate(grid):
                if rr == r:
                    continue
                for shift in range(-2, 3):
                    pairs = [(c, c + shift) for c in range(last + 1)
                             if 0 <= c + shift < w]
                    if len(pairs) < 0.85 * (last + 1):
                        continue
                    matches = sum(row[c] == other[d] for c, d in pairs)
                    if matches < 0.9 * len(pairs):
                        continue
                    if any(other[d] != bg for d in range(last + 1 + shift, w)
                           if 0 <= d < w):
                        extend = True
                        break
                if extend:
                    break

        if extend:
            for c in range(last + 1, w):
                out[r][c] = 1

    return out
